(async () => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('low');
  g.bears.directorT = 1e9;
  g.env.timeScale = 0;
  g.env.setTime(9);
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  // the boxes of the top bar and the controls, and which of them overlap
  // a change of size or safe area shows on the next frames (with reduced
  // motion every change is a very short transition), so wait for two
  window.__measure = async (label) => {
    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
    const sel = {
      wardrobe: '#btn-wardrobe', map: '#btn-map', journal: '#btn-journal', pause: '#btn-pause', bite: '#bite-pill', clock: '.clock',
      compass: '#compass', goal: '#objective', money: '#hud-money', health: '.top-left .stat.health', cooler: '#chip-cooler', lure: '#chip-lure',
      minimap: '#minimap', run: '#btn-run', primary: '#btn-primary', tool: '#btn-tool',
    };
    const vis = [];
    for (const [id, q] of Object.entries(sel)) {
      const el = document.querySelector(q);
      if (!el || el.hidden || el.closest('[hidden]')) continue;
      const b = el.getBoundingClientRect();
      if (b.width > 0) vis.push({ id, x: Math.round(b.left), y: Math.round(b.top), w: Math.round(b.width), h: Math.round(b.height) });
    }
    const hits = [];
    for (let i = 0; i < vis.length; i++)
      for (let j = i + 1; j < vis.length; j++) {
        const a = vis[i];
        const b = vis[j];
        if (a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h) hits.push(a.id + ' x ' + b.id);
      }
    const box = (id) => { const b = vis.find((v) => v.id === id); return b ? id + ' ' + b.x + ',' + b.y + ' ' + b.w + 'x' + b.h : id + ' hidden'; };
    const goal = document.getElementById('objective');
    const cut = goal.scrollWidth > goal.clientWidth + 1 ? ' (shortened with ...)' : '';
    const rot = document.getElementById('rotate');
    return label + ' ' + innerWidth + ' by ' + innerHeight + ': ' + ['compass', 'goal', 'health', 'wardrobe', 'pause', 'bite', 'clock', 'minimap'].map(box).join(' | ') + cut + (rot && !rot.hidden ? ' | ROTATE PROMPT UP' : '') + ' || overlaps: ' + (hits.join(', ') || 'none');
  };
  // the longest goal there is
  g.state.challenges.first = true;
  g.state.challenges.sell = true;
  const t0 = performance.now();
  while (performance.now() - t0 < 120000 && !document.getElementById('objective').textContent.includes('PERFECT')) await new Promise((r) => setTimeout(r, 300));
  return 'goal: ' + document.getElementById('objective').textContent;
})()
